// Replays proto/testdata/tee_bundle_vectors.json (generated by
// proto/go/inject/tee_bundle_vectors_test.go) against parseRFC3339 and
// decodeEvidenceBundle. Every outcome in the file is Go's.

import { describe, it, expect } from 'vitest'
import * as fs from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'

import {
  collateralComplete,
  decodeEvidenceBundle,
  EvidenceBundleDecodeError,
  parseRFC3339,
  type TEECollateral,
  type TEEEvidenceBundle,
} from '../src/inject/index.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any
type TimeVector = { unix_sec: number; nanos: number } | null

const here = path.dirname(fileURLToPath(import.meta.url))
const v = JSON.parse(
  fs.readFileSync(path.resolve(here, '..', '..', 'testdata', 'tee_bundle_vectors.json'), 'utf8'),
) as Json

function nanos(t: TimeVector): bigint | null {
  return t === null ? null : BigInt(t.unix_sec) * 1_000_000_000n + BigInt(t.nanos)
}

// The decoded string as Go's instant: '' is Go's zero time, which the vectors
// write as null.
function instant(s: string): bigint | null {
  if (s === '') return null
  const n = parseRFC3339(s)
  if (n === null) throw new Error(`decoded a time that does not parse: ${s}`)
  return n
}

function hexBytes(hex: string): Uint8Array {
  return Uint8Array.from(hex.match(/../g)!.map((b) => parseInt(b, 16)))
}

describe('tee_bundle_vectors.json', () => {
  it('is the schema this test expects', () => {
    expect(v.version).toBe(1)
    expect(v.rfc3339.length).toBeGreaterThan(20)
    expect(v.bundle_decode.length).toBeGreaterThan(20)
  })

  for (const c of v.rfc3339) {
    it(`parseRFC3339(${JSON.stringify(c.input)})`, () => {
      expect(parseRFC3339(c.input)).toBe(nanos(c.time))
    })
  }

  for (const c of v.bundle_decode) {
    it(`decode ${c.name}`, () => {
      const body = c.body_hex ? hexBytes(c.body_hex) : new TextEncoder().encode(c.body)
      if (c.decoded === null) {
        expect(() => decodeEvidenceBundle(body)).toThrow(EvidenceBundleDecodeError)
        return
      }
      const b = decodeEvidenceBundle(body)
      const d = c.decoded
      expect({
        mode: b.mode,
        cpu_report: b.cpu_report,
        gpu_eat: b.gpu_eat,
        event_log: b.event_log,
        app_compose: b.app_compose,
        node_pubkey: b.node_pubkey,
        operator_id: b.operator_id,
        report_data: b.report_data,
        refresh_seconds: b.refresh_seconds,
        stub: b.stub,
        collateral: b.collateral ?? null,
      }).toStrictEqual({
        mode: d.mode,
        cpu_report: d.cpu_report,
        gpu_eat: d.gpu_eat,
        event_log: d.event_log,
        app_compose: d.app_compose,
        node_pubkey: d.node_pubkey,
        operator_id: d.operator_id,
        report_data: d.report_data,
        refresh_seconds: d.refresh_seconds,
        stub: d.stub,
        collateral: d.collateral,
      })
      expect(instant(b.generated_at)).toBe(nanos(d.generated_at))

      const u = b.upstream_attestation
      if (d.upstream_attestation === null) {
        expect(u).toBeUndefined()
      } else {
        const du = d.upstream_attestation
        expect(u).toBeDefined()
        expect({
          protocol: u!.protocol,
          base_url: u!.base_url,
          report_url: u!.report_url,
          keyset_digest: u!.keyset_digest,
          carve_outs: u!.carve_outs,
        }).toStrictEqual({
          protocol: du.protocol,
          base_url: du.base_url,
          report_url: du.report_url,
          keyset_digest: du.keyset_digest,
          carve_outs: du.carve_outs,
        })
        expect(instant(u!.verified_at)).toBe(nanos(du.verified_at))
        expect(instant(u!.lease_expires_at)).toBe(nanos(du.lease_expires_at))
      }
    })
  }
})

describe('decodeEvidenceBundle', () => {
  const decode = (s: string): TEEEvidenceBundle => decodeEvidenceBundle(new TextEncoder().encode(s))

  // The aux fields reach verifyAux exactly as received, so it can refuse a
  // wrongly typed one with the tag that names it rather than see a default.
  it('keeps the aux fields as received', () => {
    const b = decode('{"nonce":5,"app_models":"x","posture":{"zero_retention":"yes"}}')
    expect(b.nonce).toBe(5)
    expect(b.app_models).toBe('x')
    expect(b.posture).toStrictEqual({ zero_retention: 'yes' })

    const n = decode('{"nonce":null}')
    expect(n.nonce).toBeNull()
    expect(n.app_models).toBeUndefined()
  })

  it('does not read a key through Object.prototype', () => {
    const b = decode('{"__proto__":{"mode":"stub"},"constructor":5}')
    expect(b.mode).toBe('')
  })

  it('accepts an ArrayBuffer', () => {
    const buf = new TextEncoder().encode('{"mode":"stub"}').buffer
    expect(decodeEvidenceBundle(buf).mode).toBe('stub')
  })
})

describe('collateralComplete', () => {
  const full: TEECollateral = {
    pck_crl_issuer_chain: 'a',
    root_ca_crl: 'b',
    pck_crl: 'c',
    tcb_info_issuer_chain: 'd',
    tcb_info: 'e',
    tcb_info_signature: 'f',
    qe_identity_issuer_chain: 'g',
    qe_identity: 'h',
    qe_identity_signature: 'i',
  }

  it('needs all nine members', () => {
    expect(collateralComplete(full)).toBe(true)
    for (const k of Object.keys(full) as (keyof TEECollateral)[]) {
      expect(collateralComplete({ ...full, [k]: '' }), k).toBe(false)
    }
    expect(collateralComplete(undefined)).toBe(false)
    expect(collateralComplete(null)).toBe(false)
  })

  // Whitespace is present, as Go's Complete compares with "" only.
  it('counts whitespace as present', () => {
    expect(collateralComplete({ ...full, pck_crl: ' ' })).toBe(true)
  })
})
